pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _putValue, uint256 _minSum, uint256 _collectAm) public {
        // Bound inputs to avoid overflow or unrealistic values
        vm.assume(_lockTime <= 1e10);
        vm.assume(_putValue <= 1e18);
        vm.assume(_minSum <= 1e18);
        vm.assume(_collectAm <= _putValue);

        // Initialize the contract
        c.Initialized();

        // Set MinSum (allowed before initialization, but here we do after? Actually need to do before initialization)
        // To avoid revert, we can set MinSum before initialization
        // But the test must work on the reference; since we call Initialized first, then SetMinSum would revert in reference.
        // So we must set MinSum before Initialized.
        // Let's restart: deploy fresh each time, but setUp() is one per test. Use vm.startPrank etc.
        // Better: remove and recreate c in each fuzz run? That's not possible. So we must set MinSum before initialization.
        // Workaround: set MinSum, then initialize, then put and collect.
        c.SetMinSum(_minSum);
        c.Initialized();

        // Provide Ether for Put
        vm.deal(address(this), _putValue);
        vm.prank(address(this));
        c.Put{value: _putValue}(_lockTime);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attempt collect (may revert if time conditions not met; we wrap in try/catch)
        try c.Collect(_collectAm) {
            // Collect succeeded
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after successful Collect");
        } catch {
            // Collect reverted; MinSum should still be unchanged
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after failed Collect");
        }
    }
}

