        // Step 3: Initialize
        c.Initialized();

        // Step 4: Attempt a second SetMinSum call - it should revert because already initialized
        // But in the mutant it would set MinSum = 0 even after initialization? No, both versions revert if intitalized.
        // So after initialization, SetMinSum cannot be called successfully.
        // Therefore the only meaningful MinSum value after initialization is the one from the first SetMinSum call.
        // In reference C: MinSum = val1
        // In mutant M: MinSum = 0 (because SetMinSum always sets to 0)

        // Step 5: Make a deposit and then call Collect to observe the state
        (bool success,) = address(c).call{value: 1 ether}(""); // fallback, calls Put(0)
        require(success);

        // Now call Collect - may revert but we can still read MinSum after
        // Just call it
        (bool colSuccess,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));
        // Ignore revert, just read state

        // The rule: MinSum must equal val1 (from the only successful SetMinSum call)
        // In reference C: MinSum == val1
        // In mutant M: MinSum != val1 (unless val1 == 0)
        assertTrue(c.MinSum() == val1, "MinSum should be equal to last SetMinSum parameter");
    }
}

