pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Initialize the contract: set MinSum and mark initialized
        c.SetMinSum(0);
        c.Initialized();

        // Fund the contract with some ether
        uint256 initialBalance = 1 ether;
        vm.deal(address(c), initialBalance);

        // Fund the caller and make a deposit so they have balance to collect
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.Put(0); // put with 0 lock time

        // Record balance before Collect
        uint256 balanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

        if (success) {
            // If successful, balance should have decreased by amount (plus possible gas, but ignore)
            assertTrue(address(c).balance <= balanceBefore - amount, "Balance should decrease by amount");
        } else {
            // If reverted, balance unchanged
            assertTrue(address(c).balance == balanceBefore, "Balance unchanged on revert");
        }
    }
}

