pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint unlockTime, uint putValue, uint collectAmount) public {
        // Bound values to avoid overflows and satisfy invariants
        vm.assume(unlockTime < 1e6);
        vm.assume(putValue < 1e18);
        vm.assume(collectAmount < 1e18);

        // Set up minimal sum
        c.SetMinSum(0);
        c.Initialized();

        // Fund the caller
        vm.deal(sender, 10 ether);

        // Make a Put call to add balance
        vm.prank(sender);
        c.Put{value: putValue}(unlockTime);

        // Now try Collect - this will call Log.AddMessage which may fail if Log not set
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: the Collect call should not revert if we put enough and time condition met
        // If Log is not set, the internal AddMessage in Collect will revert
        bool logSet = c.Log() != address(0);
        // We expect that Collect always succeeds when Log is set (reference behavior)
        // But if Log is not set (bug), Collect reverts even when conditions are met
        assertTrue(logSet || !success, "Collect should not revert when Log is set");
    }
}

