pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am) public {
        // Bound _am to avoid overflow/underflow
        _am = bound(_am, 0, 1000 ether);
        // Deploy an auxiliary LogFile to capture events
        // We need to set Log first
        address logFileAddr = address(new LogFile());
        c.SetLogFile(logFileAddr);
        c.Initialized();
        // Fund the contract so Collect can succeed
        vm.deal(address(c), 1000 ether);
        // Fund the caller
        vm.deal(address(this), 100 ether);
        // Get initial log length
        (bool success,) = logFileAddr.call(abi.encodeWithSignature("History(uint256)", 0));
        uint256 initialLen = success ? 1 : 0;
        // Actually we need the length: use low-level call to get it
        // But easier: instead we check the rule by comparing before/after log length
        // There's no direct getter for History length, so we use an alternative rule:
        // After a successful Collect, the log must have been incremented if Log is set.
        // We'll capture revert difference: in reference version, Collect may revert if Log not set? No, the bug is that Log is never set, so AddMessage fails.
        // The rule: If Log is correctly set, Collect does not revert; if Log is address(0), Collect always reverts.
        // So we test: c.SetLogFile(someNonZeroAddress) before initialization? No.
        // Simpler: We deploy a fresh C without setting Log, then try Collect, and it should revert because Log is address(0).
        // But the test must work for fuzzed inputs. The invariant: In the reference, after SetLogFile is called, Log is set; in buggy, it's never set.
        // Actually the difference is: after SetLogFile is called, the state variable Log in C is updated in ref, not in bug.
        // So the rule: calling SetLogFile with a valid address followed by Initialized, then Collect should succeed in ref, but in bug it reverts because Log.AddMessage fails when Log is address(0).
        // Let's implement that.
        // We'll deploy a new C for each test? No, we have one C.
        // Let's structure: we call SetLogFile(someNonZero) then Initialized, then call Put to add balance, then call Collect. In ref, Collect succeeds; in bug, Collect reverts.
        // So the rule: after calling SetLogFile(valid) and Initialized, a call to Collect with appropriate parameters does not revert.
        // We'll check that by wrapping Collect in try/catch and asserting the boolean.

        // Setup: set a valid Log
        address logAddr = address(new LogFile());
        c.SetLogFile(logAddr);
        c.Initialized();
        // Add some balance via Put
        c.Put{value: 1 ether}(block.timestamp);
        // Now try Collect
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 ether));
        assertTrue(ok == true);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

