import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 fundAmount, uint256 lockTime, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(withdrawAmount > 0 && withdrawAmount <= fundAmount);
        vm.assume(lockTime > 0);

        // Initialize the contract
        c.SetMinSum(1);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the caller and set lock time via Put
        vm.deal(caller, fundAmount);
        vm.prank(caller);
        c.Put(lockTime);

        // Record balance before Collect
        (uint256 unlockTime, uint256 balanceBefore) = c.Acc(caller);

        // Warp to exactly unlockTime
        vm.warp(unlockTime);

        // Call Collect with withdrawAmount
        vm.prank(caller);
        (bool success, bytes memory) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // Read balance after
        (, uint256 balanceAfter) = c.Acc(caller);

        // Rule: If tx succeeded and block.timestamp == unlockTime, then balance must have increased (due to fallback Put)
        // In reference, Collect reverts when block.timestamp == unlockTime (strict > required), so success would be false
        // In mutant, Collect succeeds and balance decreases (or if call fails, balance stays same but doesn't increase)
        // We assert the reference invariant: when timestamp == unlockTime, success must be false OR balanceAfter > balanceBefore
        // Actually simpler: For the reference, when block.timestamp == unlockTime, Collect always reverts (because > fails).
        // So for mutant, success can be true and balanceAfter < balanceBefore.
        // To distinguish, we assert: if block.timestamp == unlockTime then (success == false)
        // But the problem says "P.Collect() != M.Collect()" meaning the return/behavior differs.
        // A better general rule: When block.timestamp == unlockTime, Collect must revert.
        // So we assert: !(block.timestamp == unlockTime && success == true)
        assertTrue(!(block.timestamp == unlockTime && success));
    }
}

