contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 lockTime, uint256 minSum, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        // Bound lockTime to avoid overflow in add_uint256
        lockTime = bound(lockTime, 0, type(uint256).max - block.timestamp);
        // Bound collectAmt to deposit
        collectAmt = bound(collectAmt, 0, deposit);
        // Bound minSum to deposit
        minSum = bound(minSum, 0, deposit);

        // Setup: set MinSum and deposit
        vm.prank(caller);
        c.SetMinSum(minSum);
        vm.prank(caller);
        c.Initialized();
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Put{value: deposit}(lockTime);

        // Warp time to after unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // Attempt to collect exactly deposit (so balance == minSum when minSum == deposit)
        bool success;
        if (collectAmt > 0) {
            vm.prank(caller);
            (success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        } else {
            success = true;
        }

        // The rule: if collectAmt == deposit and minSum == deposit, then success should be true
        // Because reference allows balance >= MinSum, but mutation requires >.
        if (collectAmt == deposit && deposit > 0 && minSum == deposit) {
            assertTrue(success, "Collect should succeed when balance == MinSum");
        } else {
            assertTrue(true);
        }
    }
}

