pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 balance, uint256 lockTime, uint256 am) public {
        // Bound inputs to reasonable ranges
        minSum = bound(minSum, 0, 1e18);
        balance = bound(balance, 0, 1e18);
        lockTime = bound(lockTime, 0, 1000);
        am = bound(am, 0, 1e18);

        // Prepare: set minimum sum, fund the account, set unlock time in the past
        vm.assume(block.timestamp > lockTime + 1); // ensure we can set unlockTime in the past
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the contract and set up the holder
        vm.deal(address(0x123), balance);
        vm.prank(address(0x123));
        (bool success,) = address(c).call{value: balance}("");
        vm.assume(success);

        // Set unlockTime to block.timestamp - 1 so it's in the past
        // We need to call Put with a lockTime that results in unlockTime < block.timestamp
        // Put sets unlockTime = max(current unlockTime, block.timestamp + _lockTime)
        // Since initial unlockTime is 0, we call Put with _lockTime = 0 and then it will be block.timestamp
        // Actually, we need unlockTime < block.timestamp, so we need to move time forward after Put
        vm.prank(address(0x123));
        c.Put(0); // sets unlockTime = block.timestamp

        // Move time forward so unlockTime is in the past
        uint256 unlockTime = c.Acc(address(0x123)).unlockTime;
        vm.warp(unlockTime + 1);

        // Now test Collect with am = balance (the boundary case)
        uint256 balBefore = c.Acc(address(0x123)).balance;
        vm.prank(address(0x123));
        // The bug manifests when am == balBefore: reference accepts, mutant rejects
        // We specifically test the case that exposes the difference
        vm.assume(am == balBefore);

        // Execute Collect
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // After Collect, check the invariant:
        // If the call succeeded (reference behavior), balance should be balBefore - am = 0
        // If the call failed (mutant behavior), balance should remain balBefore
        uint256 balAfter = c.Acc(address(0x123)).balance;

        // The rule: if preconditions held (balance >= MinSum and timestamp > unlockTime),
        // then Collect should succeed and reduce balance by exactly _am when _am == balance.
        bool preconditionHolds = (balBefore >= minSum) && (block.timestamp > unlockTime);

        // In the reference, when precondition holds and am == balBefore, Collect should succeed and balance reduces to 0.
        // In the mutant, am == balBefore fails the condition (balance > _am is false) so Collect reverts.
        // So the invariant is: when precondition holds and am == balBefore, the final balance must be 0.
        if (preconditionHolds) {
            assertEq(balAfter, 0, "Bug: balance not reduced to 0 when preconditions hold and am == balBefore");
        } else {
            // If precondition doesn't hold, balance should not change
            assertEq(balAfter, balBefore, "Unexpected balance change when preconditions don't hold");
        }
    }
}

