        uint256 balanceBefore = c.Acc(caller).balance;

        // Warp to after unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Try Collect - may revert
        bool reverted;
        vm.prank(caller);
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: if Collect reverted, balance must not have changed
        if (reverted) {
            uint256 balanceAfter = c.Acc(caller).balance;
            assertTrue(balanceAfter == balanceBefore, "Balance changed despite reverted Collect");
        }
    }
}

