pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 lockTime, uint256 initialBalance, uint256 collectAmount, uint256 minSum) public {
        vm.assume(caller != address(0));
        vm.assume(initialBalance > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= initialBalance);
        vm.assume(minSum <= initialBalance);

        // Setup: set MinSum and initial deposit
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Put{value: initialBalance}(lockTime);

        // Warp time past unlock
        vm.warp(block.timestamp + lockTime + 1);

        // Record balance before Collect
        (uint256 unlockTimeBefore, uint256 balanceBefore) = c.Acc(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Read state after
        (, uint256 balanceAfter) = c.Acc(caller);

        // General rule: If Collect succeeded, the balance decreased by at most collectAmount
        // because the buggy version always decreases even if the external call fails.
        if (success) {
            assertTrue(balanceAfter <= balanceBefore);
            assertTrue(balanceBefore - balanceAfter == collectAmount || balanceBefore - balanceAfter == 0);
        } else {
            // If Collect reverted, balance should be unchanged
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 lockTime, uint256 deposit, uint256 am) public {
        vm.assume(caller != address(0));
        vm.assume(lockTime <= type(uint256).max - block.timestamp);
        vm.assume(deposit <= type(uint256).max - 1 ether);
        vm.assume(am <= deposit);

        // Initialize contract and set min sum to 0
        c.SetMinSum(0);
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Put{value: deposit}(lockTime);

        // Warp to after lock time
        vm.warp(block.timestamp + lockTime + 1);

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(caller).balance;

        // Try Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        // Get balance after
        uint256 balanceAfter = c.Acc(caller).balance;

        // The rule: balance decreased by am only if the external call succeeded
        // If the call reverted, balance unchanged
        assertTrue((!success && balanceAfter == balanceBefore) || (success && balanceAfter == balanceBefore - am));
    }
}
